data.script:
if (!draft.content.trim()) { context.fail('The draft is empty.'); }
else {
  const date = draft.processTemplate('[[date|%Y-%m-%d]]');
  const body = draft.processTemplate('[[body]]');
  const entry = '# Notes for ' + date + (body ? '\n' + body : '');
  const url = 'dayone://post?entry=' + encodeURIComponent(entry) + '&tags=' + encodeURIComponent('Daily,Notes');
  if (!app.openURL(url)) context.fail('Could not open Day One.');
}
